window.docContents[87].resolve({"/Elementary-Functions/___4___26-Integrals/#chapter-4-section-26":{"contents":"Throughout §4.26 variables are real. The indefinite identities use the stated\nopen intervals to avoid singularities and principal-log branch changes. The\ndefinite identities include finite orthogonality integrals and improper\nintegrals interpreted as limits; inverse-trigonometric entries retain their\nreal endpoint restrictions.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.26. §4.26 Integrals","id":"/Elementary-Functions/___4___26-Integrals/#chapter-4-section-26"}});